_advanceProjectiles(dt, frame) {
  if (!dt || !this.state.clams.length) return;
  let remaining = dt;
  let steps = 0;
  while (remaining > EPS && steps++ < 300) {
    const step = Math.min(remaining, 1 / 30);
    remaining -= step;
    const field = this.state.clams, fieldLength = field.length;
  for (let fieldIndex = 0; fieldIndex < fieldLength; fieldIndex++) {
    const clam = field[fieldIndex];
      clam.age += step;
      if (clam.grounded) continue;
      const previous = [...clam.pos];
      clam.velocity[1] -= GRAVITY * step;
      const next = add(previous, scale(clam.velocity, step));
      const blocked = typeof frame?.blocked === 'function' && frame.blocked(previous, next) === true;
      if (blocked) {
        this._paintPower(clam, previous);
        this._event('clam-collision', { id: clam.id, pos: [...previous], kind: clam.kind });
        this._reflect(clam, previous, frame);
        continue;
      }
      if (this._tryGoal(clam, previous, next, frame)) {
        if (this.engine?.winner != null) return;
        continue;
      }
      let actorHit = false;
      for (const actor of this._actorList(frame)) {
        if (actor.alive === false || actor.id === clam.thrower) continue;
        // Use the swept contact for admission too. Rechecking the old birth
        // point loses grazing catches even at the ordinary 60Hz throw speed.
        const bodyCenter = vec(actor.pos); bodyCenter[1] += 0.9;
        const contact = this._segmentClosestPoint(bodyCenter, previous, next);
        if (this._collectFromProjectile(clam, actor, frame, contact, bodyCenter)) {
          this.state.clams = this.state.clams.filter(item => item.id !== clam.id);
          actorHit = true;
          break;
        }
      }
      if (actorHit) continue;
      // A roof above this flight segment is not a landing surface. Missing
      // floor below an airborne clam is a gap; lose it at the live world's
      // water/fall boundary, rather than deleting a valid throw mid-arc.
      const floor = this._floorAt(frame, next[0], next[2], Math.max(previous[1], next[1]));
      const overVoid = floor === null;
      const lostInVoid = overVoid && (!Number.isFinite(frame?.fallDeathY) || next[1] <= frame.fallDeathY);
      if (lostInVoid || !overVoid && next[1] < floor - 12) {
        this.state.clams = this.state.clams.filter(item => item.id !== clam.id);
        this._event('clam-lost', { id: clam.id, kind: clam.kind, pos: [...next] });
        continue;
      }
      if (!overVoid && next[1] <= floor) {
        clam.pos = [next[0], floor, next[2]];
        this._paintPower(clam, clam.pos);
        if (clam.velocity[1] < -1 && clam.bounces < 1) {
          clam.velocity[1] = Math.abs(clam.velocity[1]) * 0.28;
          clam.velocity[0] *= 0.5;
          clam.velocity[2] *= 0.5;
          clam.bounces++;
        } else {
          clam.velocity = [0, 0, 0];
          clam.grounded = true;
        }
      } else clam.pos = next;
    }
  }
}

chargerScan:
function step(system,job,dt){
  job.prev.copy(job.pos);
  const length=Math.min(job.speed*dt,Math.max(0,job.range-job.travel));
  job.pos.copy(job.prev).addScaledVector(job.dir,length);
  const world=sweptWorldHit(G.physics,job.prev,job.pos,collision.InitRadiusForField,collision.EndRadiusForField,job.hit,true);
  let distance=world.hit?world.dist:length,ended=world.hit,normal=world.hit?world.normal.clone():null,target=null;
  const defense=system.kitDefenseCandidate?.({owner:job.owner,team:job.team,prev:job.prev,pos:job.pos,vel:job.dir,damage:job.damage,type:'beam',size:0,ghost:job.ghost,full:!!job.full});
  if(defense&&(!world.hit||defense.distance<world.dist-EPS)){distance=defense.distance;ended=true;target='defense';normal=job.dir.clone().negate();}
  const boss=G.boss?.segHit(job.prev,job.pos,collision.InitRadiusForPlayer);
  if(boss&&boss.dist<distance-EPS){distance=boss.dist;ended=true;normal=job.dir.clone().negate();target='boss';}
  const actors=job.hitCandidates||=([]);actors.length=0;
  for(const actor of G.actors){
    // Partial rounds meet allied bodies; full rounds retain teammate piercing.
    if(!actor.alive||actor===job.owner||(job.full&&actor.team===job.team)||job.seen.has(actor))continue;
    // A live fixed-step beam and the target must share one contact time.
    // Historical ghost catch-up does not span the current actor snapshot.
    const motion=!job.ghost && Math.abs(dt-SIM_DT)<=EPS ? coherentMotionStart(actor) : null;
    let end=job.pos;
    if(motion){
      job.base.set(motion.x0,motion.y0,motion.z0);
      // A last range-clipped segment expires before the tick ends. Scale the
      // target interval by that same flight duration, never later movement.
      const fraction=Math.min(1,length/(job.speed*dt));
      job.moved.set(job.pos.x-(actor.pos.x-motion.x0)*fraction,job.pos.y-(actor.pos.y-motion.y0)*fraction,job.pos.z-(actor.pos.z-motion.z0)*fraction);
      end=job.moved;
    }else job.base.copy(actor.pos);
    const t=capsuleEntry(job.prev,end,job.base,hurtboxRadius(actor,PLAYER),hurtboxHeight(actor,PLAYER),
      collision.InitRadiusForPlayer,collision.EndRadiusForPlayer);
    if(chargerActorBeforeStop(t,length,distance))actors.push({actor,d:t*length});
  }
  if(actors.length>1)actors.sort((a,b)=>a.d-b.d||String(a.actor.nid??a.actor.name).localeCompare(String(b.actor.nid??b.actor.name)));
